import React from "react";
import { NavLink } from "react-router-dom";

function BottomNav() {
    return (
        <nav className="bottom-nav">
            <NavLink
                to="/home"
                className={({ isActive }) => "nav-item" + (isActive ? " active" : "")}
            >
                <i className="material-icons-round">dashboard</i>
                <span>Home</span>
            </NavLink>

            <NavLink
                to="/calendar"
                className={({ isActive }) => "nav-item" + (isActive ? " active" : "")}
            >
                <i className="material-icons-round">calendar_today</i>
                <span>Calendar</span>
            </NavLink>

            <NavLink
                to="/layout"
                className={({ isActive }) => "nav-item" + (isActive ? " active" : "")}
            >
                <i className="material-icons-round">layers</i>
                <span>Layout</span>
            </NavLink>

            <NavLink
                to="/profile"
                className={({ isActive }) => "nav-item" + (isActive ? " active" : "")}
            >
                <i className="material-icons-round">account_circle</i>
                <span>Profile</span>
            </NavLink>
        </nav>
    );
}

export default BottomNav;
